### labwc-greeter-output
#!/usr/bin/env perl
use strict;
use warnings;

use Fcntl qw(:flock);
use File::Path qw(make_path);
use Time::HiRes qw(usleep);

my %defaults = load_defaults('/etc/default/labwc-desktop');
apply_env_overrides(
    \%defaults,
    qw(
      LABWC_GREETER_EXTERNAL_SCALE
      LABWC_GREETER_HOTPLUG_DEBOUNCE_SECONDS
      LABWC_GREETER_INTERNAL_SCALE
      LABWC_OUTPUT_EXTERNAL_PREFERRED_HEIGHT
      LABWC_OUTPUT_EXTERNAL_PREFERRED_REFRESH_HZ
      LABWC_OUTPUT_EXTERNAL_PREFERRED_WIDTH
      LABWC_OUTPUT_INTERNAL_PREFIXES
    )
);

my $mode = $ARGV[0] // q{};
if ($mode eq '--configure') {
    my ($profile) = with_config_lock(sub { configure_outputs() });
    print "${profile}\n";
    exit 0;
}
if ($mode eq '--watch') {
    watch_outputs();
    exit 0;
}

print STDERR "usage: labwc-greeter-output {--configure|--watch}\n";
exit 64;

sub configure_outputs {
    my $wlr_randr = find_command('wlr-randr');
    die "wlr-randr is unavailable\n" if !defined $wlr_randr;

    my @outputs;
    for my $attempt (1 .. 30) {
        @outputs = connected_outputs($wlr_randr);
        last if @outputs;
        usleep(100_000);
    }
    die "no Wayland outputs became available\n" if !@outputs;

    my @hdmi = grep { is_hdmi_output($_) } @outputs;
    my @external = grep { !is_internal_output($_) } @outputs;
    my @internal = grep { is_internal_output($_) } @outputs;
    my $selected = $hdmi[0] // $external[0] // $internal[0];
    die "no safe Wayland output name was found\n" if !defined $selected;

    my $profile = is_internal_output($selected) ? 'internal' : 'external';
    my $scale = validated_scale(
        $profile eq 'internal'
          ? ($defaults{LABWC_GREETER_INTERNAL_SCALE} // '1')
          : ($defaults{LABWC_GREETER_EXTERNAL_SCALE} // '1')
    );
    my $mode =
      $profile eq 'external'
      ? external_mode_for_output($wlr_randr, $selected)
      : undef;

    my @base_args =
      ('--output', $selected, '--on', '--scale', $scale, '--pos', '0,0');
    if (defined $mode) {
        system {$wlr_randr} $wlr_randr,
          @base_args[0 .. 2],
          '--mode', $mode,
          @base_args[3 .. $#base_args];
    }
    if (!defined($mode) || $? != 0) {
        system {$wlr_randr} $wlr_randr, @base_args;
    }
    die "failed to enable greeter output ${selected}\n" if $? != 0;

    for my $output_name (@outputs) {
        next if $output_name eq $selected;
        system {$wlr_randr} $wlr_randr, '--output', $output_name, '--off';
        die "failed to disable non-selected greeter output ${output_name}\n"
          if $? != 0;
    }

    return ($profile, $selected);
}

sub watch_outputs {
    my $udevadm = find_command('udevadm');
    return if !defined $udevadm;

    my $debounce = validated_debounce(
        $defaults{LABWC_GREETER_HOTPLUG_DEBOUNCE_SECONDS} // '1'
    );
    open my $monitor, '-|', $udevadm, 'monitor', '--subsystem-match=drm'
      or return;

    while (my $line = <$monitor>) {
        next if $line !~ /(?:\badd\b|\bchange\b|\bremove\b)/;
        sleep $debounce if $debounce > 0;
        eval { with_config_lock(sub { configure_outputs() }); 1 };
    }
    close $monitor;
}

sub connected_outputs {
    my ($wlr_randr) = @_;
    my @outputs;

    open my $state, '-|', $wlr_randr or return @outputs;
    while (my $line = <$state>) {
        next if $line =~ /^[[:space:]]/;
        my ($output_name) = split /[[:space:]]+/, $line, 2;
        next if !output_name_safe($output_name);
        push @outputs, $output_name;
    }
    close $state;
    return @outputs;
}

sub external_mode_for_output {
    my ($wlr_randr, $output_name) = @_;
    my @modes = output_modes($wlr_randr, $output_name);
    return undef if !@modes;

    my $preferred_width =
      validated_optional_uint(
        $defaults{LABWC_OUTPUT_EXTERNAL_PREFERRED_WIDTH} // '1920',
        640,
        16384,
      );
    my $preferred_height =
      validated_optional_uint(
        $defaults{LABWC_OUTPUT_EXTERNAL_PREFERRED_HEIGHT} // '1080',
        480,
        8640,
      );
    my $preferred_hz =
      validated_optional_uint(
        $defaults{LABWC_OUTPUT_EXTERNAL_PREFERRED_REFRESH_HZ} // '60',
        24,
        1000,
      );
    return undef if !defined $preferred_width || !defined $preferred_height;

    my $preferred_size = "${preferred_width}x${preferred_height}";
    my @size_matches = grep { $_->{size} eq $preferred_size } @modes;
    return undef if !@size_matches;

    if (defined $preferred_hz) {
        my ($exact_mode) =
          grep { $_->{rounded_hz} == $preferred_hz } @size_matches;
        return $exact_mode->{value} if defined $exact_mode;
    }

    my ($connector_preferred) = grep { $_->{preferred} } @size_matches;
    return $connector_preferred->{value} if defined $connector_preferred;

    @size_matches = sort { $b->{hz} <=> $a->{hz} } @size_matches;
    return $size_matches[0]->{value};
}

sub output_modes {
    my ($wlr_randr, $output_name) = @_;
    my @modes;
    my $in_output = 0;

    open my $state, '-|', $wlr_randr or return @modes;
    while (my $line = <$state>) {
        if ($line =~ /^\Q$output_name\E\b/) {
            $in_output = 1;
            next;
        }
        last if $line !~ /^[[:space:]]/ && $in_output;
        next if !$in_output;
        next
          if $line !~
          /^\s+(\d+)x(\d+)\s+px,\s+([0-9.]+)\s+Hz\b(.*)$/;

        my ($width, $height, $hz, $flags) = ($1, $2, $3, $4 // q{});
        push @modes, {
            hz         => $hz + 0,
            preferred  => ($flags =~ /preferred/) ? 1 : 0,
            rounded_hz => int(($hz + 0) + 0.5),
            size       => "${width}x${height}",
            value      => sprintf('%sx%s@%sHz', $width, $height, $hz),
        };
    }
    close $state;
    return @modes;
}

sub is_internal_output {
    my ($output_name) = @_;
    my @prefixes = split /[[:space:]]+/,
      ($defaults{LABWC_OUTPUT_INTERNAL_PREFIXES} // 'eDP LVDS DSI');

    for my $prefix (@prefixes) {
        next if $prefix !~ /\A[A-Za-z0-9._-]+\z/;
        return 1 if $output_name =~ /\A\Q$prefix\E(?:-|[0-9])/;
    }
    return 0;
}

sub is_hdmi_output {
    my ($output_name) = @_;
    return defined $output_name && $output_name =~ /\AHDMI(?:-|[0-9])/;
}

sub output_name_safe {
    my ($output_name) = @_;
    return defined $output_name && $output_name =~ /\A[A-Za-z0-9._-]+\z/;
}

sub validated_scale {
    my ($value) = @_;
    die "invalid greeter output scale\n"
      if !defined $value || $value !~ /\A(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)\z/;
    die "greeter output scale is outside 0.5..3\n"
      if $value < 0.5 || $value > 3;
    return $value;
}

sub validated_debounce {
    my ($value) = @_;
    die "invalid greeter hotplug debounce\n"
      if !defined $value || $value !~ /\A[0-9]+\z/;
    die "greeter hotplug debounce is outside 0..10\n"
      if $value > 10;
    return $value;
}

sub validated_optional_uint {
    my ($value, $minimum, $maximum) = @_;
    return undef if !defined $value || $value !~ /\A[0-9]+\z/;
    return undef if $value < $minimum || $value > $maximum;
    return int($value);
}

sub with_config_lock {
    my ($callback) = @_;
    my $state_dir = $ENV{XDG_STATE_HOME} // q{};
    return $callback->() if $state_dir eq q{};

    make_path($state_dir, { mode => 0700 }) if !-d $state_dir;
    open my $lock_fh, '>>', "${state_dir}/greeter-output.lock"
      or return $callback->();
    flock($lock_fh, LOCK_EX) or return $callback->();
    my @result = $callback->();
    close $lock_fh;
    return @result;
}

sub find_command {
    my ($command_name) = @_;
    return undef if $command_name !~ /\A[A-Za-z0-9._+-]+\z/;

    for my $directory (split /:/, ($ENV{PATH} // q{})) {
        next if $directory eq q{};
        my $candidate = "${directory}/${command_name}";
        return $candidate if -x $candidate && !-d $candidate;
    }
    return undef;
}

sub load_defaults {
    my ($path) = @_;
    my %values;

    return %values if !-r $path;
    open my $fh, '<', $path or return %values;
    while (my $line = <$fh>) {
        chomp $line;
        $line =~ s/^\s+//;
        $line =~ s/\s+$//;
        next if $line eq q{} || $line =~ /^#/;
        next if $line !~ /^([A-Z0-9_]+)=(.*)$/;

        my ($key, $value) = ($1, $2);
        $value =~ s/^\s+//;
        $value =~ s/\s+$//;
        if ($value =~ /\A'(.*)'\z/s || $value =~ /\A"(.*)"\z/s) {
            $value = $1;
        }
        $values{$key} = $value;
    }
    close $fh;
    return %values;
}

sub apply_env_overrides {
    my ($values, @keys) = @_;

    for my $key (@keys) {
        next if !exists $ENV{$key};
        $values->{$key} = $ENV{$key};
    }
}
### labwc-dock current
#!/bin/sh
set -eu

dock_enable_override_set=${LABWC_ENABLE_CRYSTAL_DOCK+x}
dock_enable_override_value=${LABWC_ENABLE_CRYSTAL_DOCK-}
dock_command_override_set=${LABWC_CRYSTAL_DOCK_COMMAND+x}
dock_command_override_value=${LABWC_CRYSTAL_DOCK_COMMAND-}
dock_qt_platformtheme_override_set=${LABWC_QT_PLATFORMTHEME+x}
dock_qt_platformtheme_override_value=${LABWC_QT_PLATFORMTHEME-}
dock_icon_theme_override_set=${LABWC_ICON_THEME+x}
dock_icon_theme_override_value=${LABWC_ICON_THEME-}

if [ -r /etc/default/labwc-desktop ]; then
  # shellcheck disable=SC1091
  . /etc/default/labwc-desktop
fi

if [ "$dock_enable_override_set" = x ]; then
  LABWC_ENABLE_CRYSTAL_DOCK=$dock_enable_override_value
fi
if [ "$dock_command_override_set" = x ]; then
  LABWC_CRYSTAL_DOCK_COMMAND=$dock_command_override_value
fi
if [ "$dock_qt_platformtheme_override_set" = x ]; then
  LABWC_QT_PLATFORMTHEME=$dock_qt_platformtheme_override_value
fi
if [ "$dock_icon_theme_override_set" = x ]; then
  LABWC_ICON_THEME=$dock_icon_theme_override_value
fi

desktop_enabled() {
  case "${1:-true}" in
    true|yes|1|on) return 0 ;;
    *) return 1 ;;
  esac
}

state_dir="${XDG_STATE_HOME:-${HOME}/.local/state}/labwc"
install -d -m 0700 "$state_dir"
log_path="${state_dir}/crystal-dock.log"

timestamp() {
  date -u '+%Y-%m-%dT%H:%M:%SZ'
}

log_message() {
  printf '%s %s\n' "$(timestamp)" "$1" >>"$log_path"
}

require_non_negative_integer() {
  case "${2:-}" in
    ''|*[!0123456789]*)
      log_message "invalid integer for $1: ${2:-unset}"
      exit 1
      ;;
  esac
}

request_service_action() {
  action=$1
  systemctl_cmd=$(command -v systemctl 2>/dev/null || true)
  [ -n "$systemctl_cmd" ] || {
    log_message "systemctl is unavailable for crystal-dock ${action}"
    exit 1
  }
  exec "$systemctl_cmd" --user "$action" crystal-dock.service
}

dock_prepare_qt_theme() {
  dock_home=${HOME:-}
  case "$dock_home" in
    /*) ;;
    *)
      log_message "HOME must be absolute: ${dock_home:-unset}"
      exit 1
      ;;
  esac

  dock_config_home=${XDG_CONFIG_HOME:-${dock_home}/.config}
  case "$dock_config_home" in
    /*) ;;
    *)
      log_message "XDG_CONFIG_HOME must be absolute: ${dock_config_home:-unset}"
      exit 1
      ;;
  esac
  case "$dock_config_home" in
    /|*..*|*//*|*[!ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789._/+@%=-]*)
      log_message "XDG_CONFIG_HOME contains unsupported path syntax: $dock_config_home"
      exit 1
      ;;
  esac

  dock_icon_theme=${LABWC_ICON_THEME:-Papirus-Dark}
  case "$dock_icon_theme" in
    ''|*[!ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789._+-]*)
      log_message "invalid LABWC_ICON_THEME: ${dock_icon_theme:-unset}"
      exit 1
      ;;
  esac

  qt6ct_dir="${dock_config_home}/qt6ct"
  qt6ct_config="${qt6ct_dir}/qt6ct.conf"
  qt6ct_managed_config=/etc/xdg/qt6ct/qt6ct.conf
  install -d -m 0755 "$dock_config_home" "$qt6ct_dir"

  if [ -L "$qt6ct_config" ]; then
    log_message "qt6ct config must not be a symlink: $qt6ct_config"
    exit 1
  fi
  if [ ! -e "$qt6ct_config" ]; then
    [ -f "$qt6ct_managed_config" ] && [ ! -L "$qt6ct_managed_config" ] || {
      log_message "managed qt6ct config is unavailable: $qt6ct_managed_config"
      exit 1
    }
    install -m 0644 "$qt6ct_managed_config" "$qt6ct_config"
  fi
  [ -f "$qt6ct_config" ] || {
    log_message "qt6ct config must be a regular file: $qt6ct_config"
    exit 1
  }
  qt6ct_size=$(wc -c <"$qt6ct_config")
  require_non_negative_integer qt6ct_config_size "$qt6ct_size"
  [ "$qt6ct_size" -le 65536 ] || {
    log_message "qt6ct config exceeds 65536 bytes: $qt6ct_config"
    exit 1
  }

  qt6ct_icon_theme_lines=$(
    sed -n '/^\[Appearance\]$/,/^\[/s/^icon_theme=//p' "$qt6ct_config"
  )
  if [ "$qt6ct_icon_theme_lines" != "$dock_icon_theme" ]; then
    qt6ct_temporary="${qt6ct_config}.$$.tmp"
    umask 077
    awk -v icon_theme="$dock_icon_theme" '
      BEGIN {
        in_appearance = 0
        saw_appearance = 0
        wrote_icon_theme = 0
      }
      /^\[Appearance\]$/ {
        in_appearance = 1
        saw_appearance = 1
        print
        next
      }
      /^\[/ {
        if (in_appearance && !wrote_icon_theme) {
          print "icon_theme=" icon_theme
          wrote_icon_theme = 1
        }
        in_appearance = 0
        print
        next
      }
      in_appearance && /^icon_theme=/ {
        if (!wrote_icon_theme) {
          print "icon_theme=" icon_theme
          wrote_icon_theme = 1
        }
        next
      }
      { print }
      END {
        if (in_appearance && !wrote_icon_theme) {
          print "icon_theme=" icon_theme
        } else if (!saw_appearance) {
          if (NR > 0) {
            print ""
          }
          print "[Appearance]"
          print "icon_theme=" icon_theme
        }
      }
    ' "$qt6ct_config" >"$qt6ct_temporary"
    chmod 0644 "$qt6ct_temporary"
    mv -f "$qt6ct_temporary" "$qt6ct_config"
    log_message "repaired qt6ct icon theme: $dock_icon_theme"
  fi

  XDG_CONFIG_HOME=$dock_config_home
  XDG_CONFIG_DIRS=${XDG_CONFIG_DIRS:-/etc/xdg}
  export XDG_CONFIG_HOME XDG_CONFIG_DIRS
}

case "${1:-}" in
  ''|--start)
    request_service_action start
    ;;
  --stop)
    request_service_action stop
    ;;
  --restart)
    request_service_action restart
    ;;
  --run)
    [ "$#" -eq 1 ] || {
      log_message "--run does not accept additional arguments"
      exit 1
    }
    ;;
  *)
    log_message "unsupported labwc-dock argument: $1"
    exit 1
    ;;
esac

desktop_enabled "${LABWC_ENABLE_CRYSTAL_DOCK:-true}" || exit 0

dock_command=${LABWC_CRYSTAL_DOCK_COMMAND:-crystal-dock}
case "$dock_command" in
  ''|*[!ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789._+@%=:,/\ -]*)
    log_message "invalid LABWC_CRYSTAL_DOCK_COMMAND: $dock_command"
