509:sub restart_session_components {
519:sub resume_session_components {
552:sub restart_waybar {
568:sub stop_fuzzel {
606:sub restart_dock {
    my ($state) = @_;
    my @lines = map {
        my $line = $_;
        $line =~ s/\s+$//;
        $line;
    } split /\n/, $state;
    return join "\n", @lines;
}

sub restart_session_components {
    my ($delay_us) = @_;
    return if !session_is_wayland_active();
    $delay_us = 300_000 if !defined $delay_us || $delay_us !~ /\A\d+\z/;
    usleep($delay_us);
    restart_waybar();
    restart_dock();
    return;
}

sub resume_session_components {
    return if !session_is_wayland_active();
    usleep(300_000);
    # A suspended Fuzzel may retain its per-user lock after losing its surface.
    stop_fuzzel();
    restart_waybar();
    return;
}

sub topology_restart_delay_us {
    my ($selected_output, @outputs_to_disable) = @_;
    my $delay_us = 300_000;

    return $delay_us if !defined $selected_output || !is_internal_output($selected_output);
    return $delay_us if !grep { !is_internal_output($_) } @outputs_to_disable;

    my $extra_delay_seconds = optional_uint($defaults{LABWC_OUTPUT_INTERNAL_REFRESH_DELAY_SECONDS});
    $extra_delay_seconds = 1 if !defined $extra_delay_seconds;
    return $delay_us + ($extra_delay_seconds * 1_000_000);
}

sub session_is_wayland_active {
    return 1 if defined $ENV{WAYLAND_DISPLAY} && $ENV{WAYLAND_DISPLAY} ne q{};
    return 1 if defined $ENV{SWAYSOCK} && $ENV{SWAYSOCK} ne q{};
    return (($ENV{XDG_SESSION_TYPE} // q{}) eq 'wayland') ? 1 : 0;
}

sub enabled_setting {
    my ($value) = @_;
    return 1 if !defined $value;
    return $value =~ /\A(?:true|yes|1|on)\z/i ? 1 : 0;
}

sub restart_waybar {
    return if !enabled_setting($defaults{LABWC_ENABLE_WAYBAR});

    my $systemctl = find_command('systemctl');
    return if !defined $systemctl;

    system {$systemctl} $systemctl, '--user', '--quiet', 'is-active', 'waybar.service';
    if ($? == 0) {
        system {$systemctl} $systemctl, '--user', '--no-block', 'restart', 'waybar.service';
        return;
    }

    system {$systemctl} $systemctl, '--user', '--no-block', 'start', 'waybar.service';
    return;
}

sub stop_fuzzel {
    my $runtime_dir = $ENV{XDG_RUNTIME_DIR} // "/run/user/$<";
    return if $runtime_dir !~ m{\A/};

    my $lock_path = "${runtime_dir}/labwc-fuzzel.lock";
    my $pid_path  = "${runtime_dir}/labwc-fuzzel.pid";
    open my $lock_fh, '>>', $lock_path or return;
    if (flock($lock_fh, LOCK_EX | LOCK_NB)) {
        close $lock_fh;
        unlink $pid_path if -e $pid_path;
        return;
    }

    open my $pid_fh, '<', $pid_path or return;
    my $pid = <$pid_fh> // q{};
    close $pid_fh;
    chomp $pid;
    return if $pid !~ /\A[1-9][0-9]*\z/ || $pid <= 1;
    return if !kill 0, $pid;

    kill 'TERM', $pid;
    for (1 .. 20) {
        last if !kill 0, $pid;
        usleep(50_000);
    }
    if (kill 0, $pid) {
        kill 'KILL', $pid;
        for (1 .. 20) {
            last if !kill 0, $pid;
            usleep(50_000);
        }
    }

    unlink $pid_path if !kill 0, $pid;
    close $lock_fh;
    return;
}

sub restart_dock {
    return if !enabled_setting($defaults{LABWC_ENABLE_CRYSTAL_DOCK});

    my $systemctl = find_command('systemctl');
    return if !defined $systemctl;

    system {$systemctl} $systemctl, '--user', '--no-block', 'restart',
      'crystal-dock.service';
    return;
}
