#!/usr/bin/env perl
use strict;
use warnings;

use Fcntl qw(:flock);
use File::Path qw(make_path);
use Time::HiRes qw(usleep);

my %defaults = load_defaults('/etc/default/labwc-desktop');
apply_env_overrides(
    \%defaults,
    qw(
      LABWC_ENABLE_CRYSTAL_DOCK
      LABWC_ENABLE_WAYBAR
      LABWC_OUTPUT_EXTERNAL_PREFERRED_HEIGHT
      LABWC_OUTPUT_EXTERNAL_PREFERRED_REFRESH_HZ
      LABWC_OUTPUT_EXTERNAL_PREFERRED_WIDTH
      LABWC_OUTPUT_EXTERNAL_SCALE
      LABWC_OUTPUT_FALLBACK_REFRESH_HZ
      LABWC_OUTPUT_INTERNAL_PREFERRED_HEIGHT
      LABWC_OUTPUT_INTERNAL_PREFERRED_REFRESH_HZ
      LABWC_OUTPUT_INTERNAL_PREFERRED_WIDTH
      LABWC_OUTPUT_INTERNAL_PREFIXES
      LABWC_OUTPUT_INTERNAL_REFRESH_DELAY_SECONDS
      LABWC_OUTPUT_INTERNAL_SCALE
      LABWC_OUTPUT_POLICY
      LABWC_OUTPUT_SCALE
    )
);

my $requested_mode = $ARGV[0] // q{};
exit 64
  if $requested_mode ne q{}
  && $requested_mode ne '--dpms-off'
  && $requested_mode ne '--dpms-on';

my $restart_session_chrome = with_refresh_lock(
    sub {
        return refresh_outputs($requested_mode);
    }
);

restart_session_components($restart_session_chrome) if $restart_session_chrome;
exit 0;

sub refresh_outputs {
    my ($mode) = @_;

    if ($mode eq '--dpms-off') {
        run_optional('wlopm', '--off', '*');
        return 0;
    }

    if ($mode eq '--dpms-on') {
        run_optional('wlopm', '--on', '*');
        resume_session_components();
        return 0;
    }

    my $wlr_randr = find_command('wlr-randr');
    return 0 if !defined $wlr_randr;

    run_optional('wlopm', '--on', '*');

    my $state_before = capture_command($wlr_randr);
    return 0 if $state_before eq q{};
    my $previous_topology = load_saved_topology();

    my @lines = split /\n/, $state_before;
    my @outputs = connected_outputs(@lines);
    return 0 if !@outputs;

    my ($output_plans, $outputs_to_disable) = selection_plan(\@lines, @outputs);
    return 0 if !defined $output_plans || !@{$output_plans};
    my $restart_delay_us = topology_restart_delay_us(
        $output_plans->[0]->{name},
        @{$outputs_to_disable},
    );

    for my $output_plan (@{$output_plans}) {
        enable_output(
            $wlr_randr,
            $output_plan->{name},
            $output_plan->{mode},
            $output_plan->{position},
        ) or return 0;
    }
    for my $output_name (@{$outputs_to_disable}) {
        disable_output($wlr_randr, $output_name);
    }
    $extra_delay_seconds = 1 if !defined $extra_delay_seconds;
    return $delay_us + ($extra_delay_seconds * 1_000_000);
}

sub session_is_wayland_active {
    return 1 if defined $ENV{WAYLAND_DISPLAY} && $ENV{WAYLAND_DISPLAY} ne q{};
    return 1 if defined $ENV{SWAYSOCK} && $ENV{SWAYSOCK} ne q{};
    return (($ENV{XDG_SESSION_TYPE} // q{}) eq 'wayland') ? 1 : 0;
}

sub enabled_setting {
    my ($value) = @_;
    return 1 if !defined $value;
    return $value =~ /\A(?:true|yes|1|on)\z/i ? 1 : 0;
}

sub restart_waybar {
    return if !enabled_setting($defaults{LABWC_ENABLE_WAYBAR});

    my $systemctl = find_command('systemctl');
    return if !defined $systemctl;

    system {$systemctl} $systemctl, '--user', '--quiet', 'is-active', 'waybar.service';
    if ($? == 0) {
        system {$systemctl} $systemctl, '--user', '--no-block', 'restart', 'waybar.service';
        return;
    }

    system {$systemctl} $systemctl, '--user', '--no-block', 'start', 'waybar.service';
    return;
}

sub stop_fuzzel {
    my $runtime_dir = $ENV{XDG_RUNTIME_DIR} // "/run/user/$<";
    return if $runtime_dir !~ m{\A/};

    my $lock_path = "${runtime_dir}/labwc-fuzzel.lock";
    my $pid_path  = "${runtime_dir}/labwc-fuzzel.pid";
    open my $lock_fh, '>>', $lock_path or return;
    if (flock($lock_fh, LOCK_EX | LOCK_NB)) {
        close $lock_fh;
        unlink $pid_path if -e $pid_path;
        return;
    }

    open my $pid_fh, '<', $pid_path or return;
    my $pid = <$pid_fh> // q{};
    close $pid_fh;
    chomp $pid;
    return if $pid !~ /\A[1-9][0-9]*\z/ || $pid <= 1;
    return if !kill 0, $pid;

    kill 'TERM', $pid;
    for (1 .. 20) {
        last if !kill 0, $pid;
        usleep(50_000);
    }
    if (kill 0, $pid) {
        kill 'KILL', $pid;
        for (1 .. 20) {
            last if !kill 0, $pid;
            usleep(50_000);
        }
    }

    unlink $pid_path if !kill 0, $pid;
    close $lock_fh;
    return;
}

sub restart_dock {
    return if !enabled_setting($defaults{LABWC_ENABLE_CRYSTAL_DOCK});

    my $systemctl = find_command('systemctl');
    return if !defined $systemctl;

    system {$systemctl} $systemctl, '--user', '--no-block', 'restart',
      'crystal-dock.service';
    return;
}
